from datetime import datetime
from enum import Enum
from typing import Annotated
from typing import Any
from typing import Dict
from typing import Optional
from urllib.parse import urlencode

import aiohttp
import jwt
import tenacity
from livekit.agents import JobContext
from pydantic import BaseModel
from pydantic import ConfigDict
from pydantic import Field
from tenacity import stop_after_attempt
from tenacity import wait_exponential_jitter

from agent.env import env
from agent.log import logger
from agent.schemas import profile_v1
from agent.services.interfaces.purplefish_service import FollowUpResponse
from agent.services.interfaces.purplefish_service import PronunciationDictionary
from agent.services.interfaces.purplefish_service import PronunciationEntry
from agent.util import log_retry


def get_bearer_token() -> str:
    return jwt.encode({}, env.AGENT_AUTH_TOKEN_SECRET, algorithm="HS256")


def _create_microsecond_timestamp(occurred_at: float) -> str:
    # Note - timezone is not terribly important here because as long as we are focusing on monotonic timestamps
    # the timestamp value itself will be hilariously imprecise (i.e set in the year 7000). So we don't sweat the
    # timezone not being accurate
    return datetime.fromtimestamp(occurred_at).astimezone().isoformat()


@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def get_candidate_profile(
    ctx: JobContext,
) -> Optional[profile_v1.CandidateProfileResponse]:
    params = {"roomName": ctx.job.room.name}
    caller_param = urlencode(params)

    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(
                f"{env.JOBS_API_HOST}/api/profiles?{caller_param}",
                headers={
                    "Content-Type": "application/json",
                    "Authorization": "Bearer " + get_bearer_token(),
                },
            ) as response:
                if response.status == 404:
                    logger.info(
                        f"Candidate profile not found for {caller_param}",
                        extra={"job_id": ctx.job.id, "room_name": ctx.job.room.name},
                    )
                    return None
                response.raise_for_status()
                data = await response.json()
                if data.get("modelVersion") == "v1":
                    return profile_v1.load_candidate_profile_response(data)
                else:
                    raise Exception("Unsupported modelVersion")
    except Exception as e:
        logger.error(
            f"Failed to fetch candidate profile: {e}",
            extra={"job_id": ctx.job.id, "room_name": ctx.job.room.name},
        )
        return None


@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def post_message(
    *,
    engagement_id: str,
    role: str,
    content: str,
    state_id: str,
    state_type: str,
    interrupted: bool,
    occurred_at: float,
) -> None:
    async with aiohttp.ClientSession() as session:
        async with session.post(
            f"{env.JOBS_API_HOST}/api/engagements/{engagement_id}/messages",
            json={
                "role": role,
                "content": content,
                "stateId": state_id,
                "stateType": state_type,
                "interrupted": interrupted,
                "occurredAt": _create_microsecond_timestamp(occurred_at),
            },
            headers={
                "Content-Type": "application/json",
                "Authorization": "Bearer " + get_bearer_token(),
            },
        ) as response:
            response.raise_for_status()


class AgentPhoneNumber(BaseModel):
    id: str
    number: str
    sipOutboundTrunkId: Optional[str] = None
    sipOutboundTrunkForInboundId: Optional[str] = None


class Engagement(BaseModel):
    id: str
    createdAt: Annotated[datetime, Field(alias="createdAt")]
    updatedAt: Annotated[datetime, Field(alias="updatedAt")]
    profileId: str
    roomName: Optional[str] = None
    agentPhoneNumber: Optional[AgentPhoneNumber] = None
    isNewlyCreated: Optional[bool] = True

    model_config = ConfigDict(
        populate_by_name=True,
        ser_json_timedelta="iso8601",
        ser_json_bytes="base64",
        json_schema_extra={
            "properties": {
                "createdAt": {"format": "date-time"},
                "updatedAt": {"format": "date-time"},
            }
        },
    )

    @classmethod
    def parse_datetime(cls, value: str) -> datetime:
        return datetime.fromisoformat(value.rstrip("Z"))

    @classmethod
    def validate(cls, value: Dict[str, Any]) -> "Engagement":
        if isinstance(value.get("createdAt"), str):
            value["createdAt"] = cls.parse_datetime(value["createdAt"])
        if isinstance(value.get("updatedAt"), str):
            value["updatedAt"] = cls.parse_datetime(value["updatedAt"])
        return cls(**value)

    def is_outbound_call(self) -> bool:
        return self.roomName is not None and self.roomName.startswith("profileId:")


@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def create_engagement(
    ctx: JobContext,
    candidate_profile: profile_v1.Profile,
) -> Engagement:
    async with aiohttp.ClientSession() as session:
        async with session.post(
            f"{env.JOBS_API_HOST}/api/engagements",
            json={
                "profileId": candidate_profile.id,
                "roomName": ctx.job.room.name,
            },
            headers={
                "Content-Type": "application/json",
                "Authorization": "Bearer " + get_bearer_token(),
            },
        ) as response:
            response.raise_for_status()
            data = await response.json()
            return Engagement(**data)


