@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def post_engagement_script_node(
    *,
    engagement_id: str,
    node: EngagementScriptNode,
) -> None:
    async with aiohttp.ClientSession() as session:
        async with session.post(
            f"{env.JOBS_API_HOST}/api/engagements/{engagement_id}/script-nodes",
            json={
                "id": node.id,
                "createdAt": node.created_at.strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                "title": node.title,
                "prompt": node.prompt,
                "followPromptStrictly": node.follow_prompt_strictly,
                "evaluationCriteria": node.evaluation_criteria,
                "conditionToEnter": {
                    "scriptNodeId": node.condition_to_enter.script_node_id,
                    "evaluationMatches": node.condition_to_enter.evaluation_matches,
                }
                if node.condition_to_enter
                else None,
                "evaluatedConditionToEnter": {
                    "evaluationResult": node.evaluated_condition_to_enter.evaluation_result,
                    "evaluationReasoning": node.evaluated_condition_to_enter.evaluation_reasoning,
                }
                if node.evaluated_condition_to_enter
                else None,
            },
            headers={
                "Content-Type": "application/json",
                "Authorization": "Bearer " + get_bearer_token(),
            },
        ) as response:
            response.raise_for_status()


