@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def update_transfer_status(engagement_id: str, success: bool = True) -> None:
    """
    Update the transfer status for an engagement.

    Args:
        engagement_id: The ID of the engagement
        success: Boolean indicating if the transfer succeeded
    """
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {get_bearer_token()}",
    }

    data = {"success": success}

    async with aiohttp.ClientSession() as session:
        async with session.patch(
            f"{env.JOBS_API_HOST}/api/engagements/{engagement_id}/transfer",
            headers=headers,
            json=data,
        ) as response:
            response.raise_for_status()


