async def update_profile_schedule(profile_id: str, scheduled_at: str) -> None:
    """
    Update the schedule for a profile.

    Args:
        profile_id: The ID of the profile to update
        scheduled_at: The new scheduled datetime in ISO format
    """
    logger.info(
        "Updating profile schedule",
        extra={"profile_id": profile_id, "scheduled_at": scheduled_at},
    )
    async with aiohttp.ClientSession() as session:
        async with session.patch(
            f"{env.JOBS_API_HOST}/api/profiles/{profile_id}/reschedule",
            headers={
                "Content-Type": "application/json",
                "Authorization": "Bearer " + get_bearer_token(),
            },
            json={
                "scheduledAt": scheduled_at,
                "utc": True,
            },
        ) as response:
            response.raise_for_status()


@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def trigger_followup(engagement_id: str) -> FollowUpResponse:
    """
    Trigger a follow up for an engagement.

    Args:
        engagement_id: The ID of the engagement to trigger follow up for

    Returns:
        FollowUpResponse: Response containing success status and confirmation requirements
    """
    logger.info(
        "Triggering follow up for engagement",
        extra={"engagement_id": engagement_id},
    )

    async with aiohttp.ClientSession() as session:
        async with session.post(
            f"{env.JOBS_API_HOST}/api/agent/rpc",
            headers={
                "Content-Type": "text/plain",
                "Authorization": "Bearer " + get_bearer_token(),
            },
            json={
                "actionName": "triggerFollowup",
                "input": {"engagementId": engagement_id},
            },
        ) as response:
            response.raise_for_status()
            data = await response.json()
            logger.info(
                "Follow up trigger response",
                extra={
                    "engagement_id": engagement_id,
                    "response": data,
                },
            )
            return FollowUpResponse(
                success=data.get("success", False),
                should_confirm=data.get("shouldConfirm", False),
                number_of_emails=data.get("numberOfEmails"),
                message=data.get("message"),
            )


